  "check_code": """"Deterministic post-state checks for the evidence-reference mutation."""

from __future__ import annotations

import re
import sqlite3
from pathlib import Path


ARTIFACT_ID = "ART-2025-017-DECK-01"
TARGET_EVIDENCE_ID = "EVD-2025-017-011"


def _database(workspace) -> Path:
    return Path(workspace).resolve().parent / "system" / "business_analysis_evidence" / "state.db"


def _rows(workspace, query, params=()):
    connection = sqlite3.connect(_database(workspace))
    connection.row_factory = sqlite3.Row
    try:
        return [dict(row) for row in connection.execute(query, params).fetchall()]
    finally:
        connection.close()


def _normalized(value) -> str:
    return re.sub(r"[\s_\-—–·,，。:：/\\()（）]+", "", str(value or "")).casefold()


def _is_slide_twelve(value) -> bool:
    text = _normalized(value)
    return "12" in text and any(marker in text for marker in ("页", "slide", "p"))


def _describes_six_pilot_devices(value) -> bool:
    text = _normalized(value)
    has_six = "6" in text or "六" in text
    has_pilot = "试点" in text or "pilot" in text
    has_device = any(word in text for word in ("终端", "设备", "device"))
    return has_six and has_pilot and has_device


def check_new_pilot_reference(workspace):
    rows = _rows(
        workspace,
        """
        SELECT artifact_id, evidence_id, quoted_metric, quoted_value, quoted_unit,
               quote_filter_version, citation_locator, citation_text, scope_key, created_by
        FROM artifact_evidence_refs
        WHERE artifact_id = ? AND evidence_id = ?
        """,
        (ARTIFACT_ID, TARGET_EVIDENCE_ID),
    )
    if len(rows) != 1:
        return {"score": 0, "detail": f"expected exactly one target reference, found {len(rows)}"}
    row = rows[0]
    checks = {
        "quoted_metric": _normalized(row["quoted_metric"]) == "pilotdevices",
        "quoted_value": row["quoted_value"] == 6,
        "quoted_unit": _normalized(row["quoted_unit"]) in {"count", "台", "设备数", "终端数"},
        "quote_filter_version": _normalized(row["quote_filter_version"]) == "policyexportv2",
        "citation_locator": _is_slide_twelve(row["citation_locator"]),
        "citation_text": _describes_six_pilot_devices(row["citation_text"]),
        "scope_key": _normalized(row["scope_key"]) == "scenario2025017",
        "created_by": _normalized(row["created_by"]) == "usrsup014",
    }
    failed = [name for name, passed in checks.items() if not passed]
    if failed:
        return {"score": 0, "detail": "target reference has incorrect fields: " + ", ".join(failed)}
    return {"score": 1, "detail": "matched pilot-device evidence is linked to slide 12 with the source value and provenance"}


def check_existing_refs_preserved(workspace):
    expected = {
        "REF-2025-017-010": (
            "EVD-2025-017-010", "crash_occurrences", 6, "count", "telemetry-filter-v2",
            "第6页", "评审稿按刷新后的会话去重口径展示6次相关崩溃。", "SCENARIO_2025_017",
            "USR-SUP-014", "2025-01-21T17:02:34+08:00",
        ),
        "REF-2025-017-019": (
            "EVD-2025-017-019", "affected_sessions", 2, "count", "telemetry-filter-v1",
            "第9页脚注1", "另有2个早期会话仅保留索引，源记录已被清理。", "SCENARIO_2025_017",
            "USR-SUP-014", "2025-01-22T10:06:41+08:00",
        ),
        "REF-2025-017-020": (
            "EVD-2025-017-020", "dump_files_written", 1, "count", "dump-index-v1",
            "第9页脚注2", "一个转储索引缺少对应二进制文件，尚不能复核调用栈。", "SCENARIO_2025_017",
            "USR-SUP-014", "2025-01-22T10:09:53+08:00",
        ),
    }
    rows = _rows(
        workspace,
        """
        SELECT reference_id, evidence_id, quoted_metric, quoted_value, quoted_unit,
               quote_filter_version, citation_locator, citation_text, scope_key, created_by, created_at
        FROM artifact_evidence_refs
        WHERE artifact_id = ?
        ORDER BY reference_id
        """,
        (ARTIFACT_ID,),
    )
    by_id = {row["reference_id"]: row for row in rows}
    for reference_id, values in expected.items():
        row = by_id.get(reference_id)
        if row is None:
            return {"score": 0, "detail": f"existing reference removed: {reference_id}"}
        actual = (
            row["evidence_id"], row["quoted_metric"], row["quoted_value"], row["quoted_unit"],
            row["quote_filter_version"], row["citation_locator"], row["citation_text"], row["scope_key"],
            row["created_by"], row["created_at"],
        )
        if actual != values:
            return {"score": 0, "detail": f"existing reference changed: {reference_id}"}
    evidence_ids = [row["evidence_id"] for row in rows]
    allowed_ids = {"EVD-2025-017-010", "EVD-2025-017-019", "EVD-2025-017-020", TARGET_EVIDENCE_ID}
    if len(rows) not in {3, 4} or not set(evidence_ids).issubset(allowed_ids) or evidence_ids.count(TARGET_EVIDENCE_ID) > 1:
        return {"score": 0, "detail": "target artifact contains unexpected added or duplicate references"}
    return {"score": 1, "detail": "all three historical references are unchanged and no unrelated reference was added"}
